begin;
select plan(34);
insert into public.agencies(id,name,code) values('14000000-0000-0000-0000-000000000001','Fence fixture','P2-FENCE');
insert into public.enrollment_applications(id,agency_id,status,data) values('44000000-0000-0000-0000-000000000001','14000000-0000-0000-0000-000000000001','draft','{"values":{"first_name":"Manual"},"wizard":{"confirmed":["first_name"]}}');
insert into public.enrollment_application_documents(id,application_id,category,filename,storage_path,metadata) values('54000000-0000-0000-0000-000000000001','44000000-0000-0000-0000-000000000001','Passport','a.pdf','44000000-0000-0000-0000-000000000001/a.pdf','{}');
insert into public.enrollment_document_extraction_jobs(id,document_id,application_id) values('64000000-0000-0000-0000-000000000001','54000000-0000-0000-0000-000000000001','44000000-0000-0000-0000-000000000001');
create temporary table leases(token uuid);
grant all on leases to service_role;
set local role service_role;
insert into leases select lease_token from public.portal_claim_document_extraction_job();
select ok((select token is not null from leases),'claim mints a lease token');
select is((select state from public.enrollment_document_extraction_jobs where id='64000000-0000-0000-0000-000000000001'),'processing','claim retains processing state');
select is(public.portal_finish_document_extraction_job('64000000-0000-0000-0000-000000000001',gen_random_uuid(),'{"extracted":{}}',null,'{}'),false,'wrong lease completion denied');
update public.enrollment_document_extraction_jobs set lease_expires_at=now()-interval '1 second' where id='64000000-0000-0000-0000-000000000001';
select is(public.portal_fail_document_extraction_job('64000000-0000-0000-0000-000000000001',(select token from leases),'timeout','late',true,60),false,'expired lease failure denied');
update public.enrollment_document_extraction_jobs set lease_expires_at=now()+interval '4 minutes' where id='64000000-0000-0000-0000-000000000001';
-- Simulates a manual metadata write while the provider is in flight.
update public.enrollment_application_documents set metadata='{"extraction":{"confirmed":{"first_name":"Manual during provider"},"status":"confirmed"},"manual_note":"keep"}' where id='54000000-0000-0000-0000-000000000001';
select is(public.portal_finish_document_extraction_job('64000000-0000-0000-0000-000000000001',(select token from leases),'{"extracted":{"first_name":"Candidate","last_name":"Lovelace"},"confirmed":{},"status":"unreviewed","source":{}}','synthetic','{}'),true,'current lease completes atomically');
select is((select metadata#>>'{extraction,confirmed,first_name}' from public.enrollment_application_documents where id='54000000-0000-0000-0000-000000000001'),'Manual during provider','latest manual confirmation preserved');
select is((select metadata->>'manual_note' from public.enrollment_application_documents where id='54000000-0000-0000-0000-000000000001'),'keep','unrelated metadata preserved');
select is((select data#>>'{values,first_name}' from public.enrollment_applications where id='44000000-0000-0000-0000-000000000001'),'Manual','confirmed application value preserved');
select is((select data#>>'{values,last_name}' from public.enrollment_applications where id='44000000-0000-0000-0000-000000000001'),'Lovelace','empty field receives candidate');
select is((select count(*)::int from public.enrollment_document_extraction_attempts where job_id='64000000-0000-0000-0000-000000000001'),1,'one successful attempt recorded');
select is(public.portal_finish_document_extraction_job('64000000-0000-0000-0000-000000000001',(select token from leases),'{"extracted":{}}',null,'{}'),false,'duplicate completion denied');
update public.enrollment_document_extraction_jobs set state='cancelled',lease_token=(select token from leases),lease_expires_at=now()+interval '4 minutes' where id='64000000-0000-0000-0000-000000000001';
select is(public.portal_finish_document_extraction_job('64000000-0000-0000-0000-000000000001',(select token from leases),'{"extracted":{}}',null,'{}'),false,'cancelled job rejects late success');
select is(public.portal_fail_document_extraction_job('64000000-0000-0000-0000-000000000001',(select token from leases),'network','late',true,60),false,'cancelled job rejects late failure');
select is((select count(*)::int from public.enrollment_document_extraction_attempts where job_id='64000000-0000-0000-0000-000000000001'),1,'cancelled callbacks add no attempts');
update public.enrollment_document_extraction_jobs set state='queued',next_attempt_at=now() where id='64000000-0000-0000-0000-000000000001';
select ok((select lease_token<>(select token from leases) from public.portal_claim_document_extraction_job()),'reclaim mints a distinct token');
update leases set token=(select lease_token from public.enrollment_document_extraction_jobs where id='64000000-0000-0000-0000-000000000001');
update public.enrollment_document_extraction_jobs set lease_expires_at=now()-interval '1 second' where id='64000000-0000-0000-0000-000000000001';
select ok((select lease_token<>(select token from leases) from public.portal_claim_document_extraction_job()),'expired job reclaim rotates token');
select is(public.portal_finish_document_extraction_job('64000000-0000-0000-0000-000000000001',(select token from leases),'{"extracted":{}}',null,'{}'),false,'previous worker cannot complete reclaimed job');
update leases set token=(select lease_token from public.enrollment_document_extraction_jobs where id='64000000-0000-0000-0000-000000000001');
select is(public.portal_fail_document_extraction_job('64000000-0000-0000-0000-000000000001',(select token from leases),'provider','synthetic failure',true,60),true,'current lease records failure');
select is((select metadata#>>'{extraction,confirmed,first_name}' from public.enrollment_application_documents where id='54000000-0000-0000-0000-000000000001'),'Manual during provider','failure preserves confirmation too');
select is(public.portal_fail_document_extraction_job('64000000-0000-0000-0000-000000000001',(select token from leases),'provider','duplicate',true,60),false,'duplicate failure denied');
-- P05-03: provider operation receipt is lease-fenced, survives a retryable requeue and is dropped on every terminal state.
reset role;
insert into public.enrollment_document_extraction_jobs(id,document_id,application_id) values('64000000-0000-0000-0000-000000000002','54000000-0000-0000-0000-000000000001','44000000-0000-0000-0000-000000000001');
set local role service_role;
update leases set token=(select lease_token from public.portal_claim_document_extraction_job());
select is(public.portal_record_document_job_operation('64000000-0000-0000-0000-000000000002',gen_random_uuid(),'azure-document-intelligence','op-1'),false,'wrong lease cannot record an operation');
select is(public.portal_record_document_job_operation('64000000-0000-0000-0000-000000000002',(select token from leases),'azure-document-intelligence','op-1'),true,'current lease records the operation');
select is((select operation_id from public.enrollment_document_extraction_operations where job_id='64000000-0000-0000-0000-000000000002'),'op-1','receipt is stored');
select is(public.portal_record_document_job_operation('64000000-0000-0000-0000-000000000002',(select token from leases),'azure-document-intelligence',null),true,'current lease clears the operation');
select is((select count(*)::int from public.enrollment_document_extraction_operations where job_id='64000000-0000-0000-0000-000000000002'),0,'cleared receipt is gone');
select is(public.portal_record_document_job_operation('64000000-0000-0000-0000-000000000002',(select token from leases),'azure-document-intelligence','op-1'),true,'receipt recorded again');
select is(public.portal_fail_document_extraction_job('64000000-0000-0000-0000-000000000002',(select token from leases),'timeout','retry',true,60),true,'retryable failure requeues');
select is((select count(*)::int from public.enrollment_document_extraction_operations where job_id='64000000-0000-0000-0000-000000000002'),1,'retryable requeue keeps the receipt');
update public.enrollment_document_extraction_jobs set next_attempt_at=now() where id='64000000-0000-0000-0000-000000000002';
update leases set token=(select lease_token from public.portal_claim_document_extraction_job());
update public.enrollment_document_extraction_jobs set lease_expires_at=now()+interval '4 minutes' where id='64000000-0000-0000-0000-000000000002';
select is(public.portal_record_document_job_operation('64000000-0000-0000-0000-000000000002',gen_random_uuid(),'azure-document-intelligence','op-stale'),false,'a stale worker cannot replace the receipt');
select is(public.portal_finish_document_extraction_job('64000000-0000-0000-0000-000000000002',(select token from leases),'{"extracted":{}}','op-1','{}'),true,'current lease completes');
select is((select count(*)::int from public.enrollment_document_extraction_operations where job_id='64000000-0000-0000-0000-000000000002'),0,'success drops the receipt');
reset role;
insert into public.enrollment_document_extraction_jobs(id,document_id,application_id) values('64000000-0000-0000-0000-000000000003','54000000-0000-0000-0000-000000000001','44000000-0000-0000-0000-000000000001');
set local role service_role;
update leases set token=(select lease_token from public.portal_claim_document_extraction_job());
select public.portal_record_document_job_operation('64000000-0000-0000-0000-000000000003',(select token from leases),'azure-document-intelligence','op-2');
update public.enrollment_document_extraction_jobs set state='cancelled',lease_expires_at=null where id='64000000-0000-0000-0000-000000000003';
select is((select count(*)::int from public.enrollment_document_extraction_operations where job_id='64000000-0000-0000-0000-000000000003'),0,'cancellation drops the receipt');
reset role;
select is(has_function_privilege('authenticated','public.portal_record_document_job_operation(uuid,uuid,text,text)','execute') or has_table_privilege('authenticated','public.enrollment_document_extraction_operations','select'),false,'browser role cannot reach the operation receipt');
select is(has_function_privilege('authenticated','public.portal_finish_document_extraction_job(uuid,uuid,jsonb,text,jsonb)','execute'),false,'browser role cannot invoke privileged completion');
select * from finish();
rollback;
